def _parse_arxiv_atom_response(xml_text: str) -> List[Dict[str, Any]]:
    """Parse arXiv Atom XML response into paper dictionaries."""
    results = []
    try:
        root = ET.fromstring(xml_text)
        for entry in root.findall('atom:entry', ARXIV_NS):
            id_elem = entry.find('atom:id', ARXIV_NS)
            if id_elem is None or id_elem.text is None:
                continue
            paper_id = id_elem.text.split('/abs/')[-1]
            short_id = paper_id.split('v')[0] if 'v' in paper_id else paper_id
            title_elem = entry.find('atom:title', ARXIV_NS)
            title = title_elem.text.strip().replace('\n', ' ') if title_elem is not None and title_elem.text else ''
            authors = []
            for author in entry.findall('atom:author', ARXIV_NS):
                name_elem = author.find('atom:name', ARXIV_NS)
                if name_elem is not None and name_elem.text:
                    authors.append(name_elem.text)
            summary_elem = entry.find('atom:summary', ARXIV_NS)
            abstract = summary_elem.text.strip().replace('\n', ' ') if summary_elem is not None and summary_elem.text else ''
            categories = []
            for cat in entry.findall('arxiv:primary_category', ARXIV_NS):
                term = cat.get('term')
                if term:
                    categories.append(term)
            for cat in entry.findall('atom:category', ARXIV_NS):
                term = cat.get('term')
                if term and term not in categories:
                    categories.append(term)
            published_elem = entry.find('atom:published', ARXIV_NS)
            published = published_elem.text if published_elem is not None and published_elem.text else ''
            pdf_url = None
            for link in entry.findall('atom:link', ARXIV_NS):
                if link.get('title') == 'pdf':
                    pdf_url = link.get('href')
                    break
            if not pdf_url:
                pdf_url = f'http://arxiv.org/pdf/{paper_id}'
            results.append({'id': short_id, 'versioned_id': paper_id, 'title': title, 'authors': authors, 'abstract': abstract, 'categories': categories, 'published': published, 'url': pdf_url, 'resource_uri': f'arxiv://{short_id}'})
    except ET.ParseError as e:
        logger.error(f'Failed to parse arXiv XML response: {e}')
        raise ValueError(f'Failed to parse arXiv API response: {e}')
    return results

tools.search:_parse_opensearch_total_res.source:
def _parse_opensearch_total_results(xml_text: str) -> Optional[int]:
    """Return arXiv OpenSearch totalResults, or None if the feed omits it."""
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return None
    elem = root.find('opensearch:totalResults', ARXIV_NS)
    if elem is None:
        for child in list(root):
            tag = child.tag.rsplit('}', 1)[-1]
            if tag == 'totalResults':
                elem = child
                break
    if elem is None or elem.text is None:
        return None
    try:
        return int(elem.text.strip())
    except ValueError:
        return None

tools.search:_rate_limited_response.source:
def _rate_limited_response(message: str | None=None, *, retry_after_seconds: float | None=None, status_code: int=429) -> List[types.TextContent]:
    """Soft rate-limit result so callers can continue without a bare Error: stall."""
    extra: Dict[str, Any] = {'http_status': status_code}
    if retry_after_seconds is None:
        retry_after_seconds = _DEFAULT_RETRY_AFTER_SECONDS
    extra['retry_after_seconds'] = retry_after_seconds
    return _status_response('rate_limited', message or RATE_LIMIT_MESSAGE, **extra)

tools.search:_status_response.source:
def _status_response(status: str, message: str, **extra: Any) -> List[types.TextContent]:
    """Return a structured {status, message} tool payload."""
    payload: Dict[str, Any] = {'status': status, 'message': message}
    payload.update(extra)
    return [types.TextContent(type='text', text=json.dumps(payload, indent=2))]

